import { useState, useEffect } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getApiUrl } from '@/lib/apiConfig';
import { apiRequest } from '@/lib/queryClient';
import { AppleWheelDatePicker } from "@/components/ui/apple-wheel-picker";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Clock, Loader2 } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

interface BookingCalendarProps {
  platform: string;
  providerId: number;
  onSlotSelected: (slotDetails: {
    slotId: number;
    lockToken: string;
    expiresAt: Date;
    startTime: Date;
    endTime: Date;
  }) => void;
  bookingMode: 'SINGLE_SLOT' | 'MULTI_SLOT';
  /** Called when the user taps "Request Custom Date" on the empty-slots message */
  onRequestCustomDate?: () => void;
}

interface AvailabilitySlot {
  id: number;
  providerId: number;
  platform: string;
  start: string;
  end: string;
  status: 'AVAILABLE' | 'HELD' | 'BOOKED';
  timezone: string;
}

const pad2 = (n: number) => String(n).padStart(2, '0');
/** Local-date → 'YYYY-MM-DD' (no UTC shift). */
const dateToStr = (d: Date) => `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
/** 'YYYY-MM-DD' → local Date at midnight. */
const strToDate = (s: string) => {
  const [y, m, d] = s.split('-').map(Number);
  return new Date(y, (m || 1) - 1, d || 1);
};

export function BookingCalendar({ platform, providerId, onSlotSelected, bookingMode, onRequestCustomDate }: BookingCalendarProps) {
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(new Date());
  const [selectedSlot, setSelectedSlot] = useState<AvailabilitySlot | null>(null);
  const [lockingSlotId, setLockingSlotId] = useState<number | null>(null);
  const { toast } = useToast();

  const fromDate = selectedDate || new Date();
  const toDate = new Date(fromDate);
  toDate.setDate(toDate.getDate() + 7);

  const { data, isLoading, error, refetch } = useQuery<{ success: boolean; slots: AvailabilitySlot[]; count: number }>({
    queryKey: ['/api/bookings/availability', platform, providerId, fromDate.toISOString(), toDate.toISOString()],
    queryFn: async () => {
      const params = new URLSearchParams({
        platform,
        providerId: providerId.toString(),
        from: fromDate.toISOString(),
        to: toDate.toISOString(),
      });
      const res = await fetch(getApiUrl(`/api/bookings/availability?${params}`), {
        credentials: 'include',
      });
      if (!res.ok) throw new Error('Failed to fetch availability');
      return res.json();
    },
    enabled: !!selectedDate,
    retry: 1,
    retryDelay: 1000,
  });

  const effectiveSlots = data?.slots || [];

  // Reset selection when date changes
  useEffect(() => {
    setSelectedSlot(null);
  }, [selectedDate]);

  const handleSlotClick = async (slot: AvailabilitySlot) => {
    if (slot.status !== 'AVAILABLE') {
      toast({
        title: "Slot Unavailable",
        description: "This time slot is already booked or held. Please select another time.",
        variant: "destructive",
      });
      return;
    }
    if (lockingSlotId !== null) return;

    // Acquire the REAL server-side lock. Checkout's atomic claim requires the
    // DB-persisted lockToken + status='held' — a client-generated token can
    // never satisfy it, and without this call the slot is not protected from
    // a concurrent customer.
    setLockingSlotId(slot.id);
    try {
      const res = await apiRequest('POST', '/api/provider-slots/lock', {
        slotId: slot.id,
        platformId: slot.platform || platform,
      });
      const lock = await res.json();
      if (!lock?.lockToken) {
        throw new Error(lock?.error || 'Could not reserve this time slot');
      }

      setSelectedSlot(slot);

      const startTime = new Date(slot.start);
      const endTime = new Date(slot.end);

      onSlotSelected({
        slotId: slot.id,
        lockToken: lock.lockToken,
        expiresAt: new Date(lock.lockExpiresAt),
        startTime,
        endTime,
      });

      toast({
        title: "Time Slot Reserved ✓",
        description: `Held for 5 minutes: ${startTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`,
      });
    } catch (err: any) {
      toast({
        title: "Slot Unavailable",
        description: err?.message?.includes('held by another')
          ? "Another customer is holding this time slot. Please try again shortly or pick another time."
          : "Could not reserve this time slot. Please try another time or sign in and retry.",
        variant: "destructive",
      });
      refetch();
    } finally {
      setLockingSlotId(null);
    }
  };

  const slotsForSelectedDate = effectiveSlots.filter(slot => {
    if (!selectedDate) return false;
    const slotDate = new Date(slot.start);
    return (
      slotDate.getDate() === selectedDate.getDate() &&
      slotDate.getMonth() === selectedDate.getMonth() &&
      slotDate.getFullYear() === selectedDate.getFullYear()
    );
  });

  return (
    <div className="space-y-6">
      <div>
        <h3 className="text-lg font-semibold mb-4">Select Date</h3>
        {/* iOS-style finger-scroll wheel (day · month · year). The wheel speaks
            'YYYY-MM-DD'; we adapt to/from Date and clamp any past pick to today
            to preserve the old minDate guard. */}
        <AppleWheelDatePicker
          value={dateToStr(selectedDate || new Date())}
          onChange={(s) => {
            let d = strToDate(s);
            const today = new Date();
            today.setHours(0, 0, 0, 0);
            if (d < today) d = today;
            setSelectedDate(d);
          }}
          minYear={new Date().getFullYear()}
          maxYear={new Date().getFullYear() + 1}
        />
      </div>

      {selectedDate && (
        <div>
          <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
            <Clock className="w-5 h-5" />
            Available Time Slots
          </h3>

          {isLoading && (
            <div className="flex items-center justify-center py-8">
              <Loader2 className="w-8 h-8 animate-spin text-[#B8932F]" />
              <span className="ml-2 text-gray-600">Loading availability...</span>
            </div>
          )}

          {error && (
            <Card className="border-amber-200 bg-white dark:bg-amber-900/20">
              <CardContent className="p-4">
                <p className="text-sm text-amber-800 dark:text-amber-200 mb-2">
                  Could not load availability for this provider. Please try again.
                </p>
                <Button 
                  variant="outline" 
                  size="sm"
                  onClick={() => refetch()}
                  className="text-amber-700 border-amber-300"
                >
                  Retry
                </Button>
              </CardContent>
            </Card>
          )}

          {!isLoading && !error && slotsForSelectedDate.length === 0 && (
            <Card className="border-yellow-200 bg-white dark:bg-white">
              <CardContent className="p-4 space-y-3">
                <p className="text-sm text-yellow-800 dark:text-yellow-200">
                  No available slots for this date. Please select another day or send a custom request.
                </p>
                {onRequestCustomDate && (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={onRequestCustomDate}
                    className="w-full border-yellow-400 text-yellow-900 dark:text-yellow-200 hover:bg-yellow-50 dark:hover:bg-yellow-900/40"
                  >
                    Request Custom Date →
                  </Button>
                )}
              </CardContent>
            </Card>
          )}

          {!isLoading && !error && slotsForSelectedDate.length > 0 && (
            <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 gap-2">
              {slotsForSelectedDate.map((slot) => {
                const startTime = new Date(slot.start);
                const timeLabel = startTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
                const isSelected = selectedSlot?.id === slot.id;
                const isAvailable = slot.status === 'AVAILABLE';
                const isLocking = lockingSlotId === slot.id;

                return (
                  <Button
                    key={slot.id}
                    variant={isSelected ? "default" : "outline"}
                    onClick={() => handleSlotClick(slot)}
                    disabled={!isAvailable || lockingSlotId !== null}
                    className={`${
                      isSelected
                        ? 'bg-gradient-to-r from-[#B8932F] to-[#B8932F] text-white'
                        : isAvailable
                        ? 'hover:border-[#D4AF37]'
                        : 'opacity-50 cursor-not-allowed'
                    }`}
                    data-testid={`time-slot-${timeLabel}`}
                  >
                    {isLocking ? <Loader2 className="w-4 h-4 animate-spin" /> : timeLabel}
                  </Button>
                );
              })}
            </div>
          )}
        </div>
      )}

      {selectedSlot && (
        <Card className="border-green-200 bg-green-50 dark:bg-white">
          <CardContent className="p-4">
            <p className="text-sm text-green-800 dark:text-green-200">
              ✓ Selected: {new Date(selectedSlot.start).toLocaleDateString()} at {new Date(selectedSlot.start).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
            </p>
            <p className="text-xs text-green-700 dark:text-green-300 mt-1">
              Reserved for 5 minutes - complete your booking to confirm
            </p>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

export default BookingCalendar;
